class MaxQueue {
  constructor() {
    this.queue = new Deque();
    this.monoDecrDeque = new Deque();
  }

  max() {
    return this.monoDecrDeque.peekFront();
  }

  pop() {
    const val = this.queue.popFront();
    // Check if we are popping the max
    if (val === this.monoDecrDeque.peekFront()) {
      this.monoDecrDeque.popFront();
    }
  }

  push(val) {
    this.queue.pushBack(val);
    // Remove elements from the monotonic deque that can never be the max
    while (!this.monoDecrDeque.empty() && this.monoDecrDeque.peekBack() < val) {
      this.monoDecrDeque.popBack();
    }
    this.monoDecrDeque.pushBack(val);
  }
}

class DequeNode {
  constructor(val) {
    this.val = val;
    this.next = null;
    this.prev = null;
  }
}

class Deque {
  constructor() {
    this.head = null;
    this.tail = null;
    this._size = 0;
  }

  empty() {
    return !this.head;
  }

  size() {
    return this._size;
  }

  peekFront() {
    if (this.empty()) {
      throw new Error("empty deque");
    }
    return this.head.val;
  }

  peekBack() {
    if (this.empty()) {
      throw new Error("empty deque");
    }
    return this.tail.val;
  }

  pushBack(val) {
    const newNode = new DequeNode(val);
    if (this.tail) {
      this.tail.next = newNode;
      newNode.prev = this.tail;
    }
    this.tail = newNode;
    if (!this.head) {
      this.head = newNode;
    }
    this._size++;
  }

  pushFront(val) {
    const newNode = new DequeNode(val);
    if (this.head) {
      this.head.prev = newNode;
      newNode.next = this.head;
    }
    this.head = newNode;
    if (!this.tail) {
      this.tail = newNode;
    }
    this._size++;
  }

  popBack() {
    if (this.empty()) {
      throw new Error("empty deque");
    }
    const val = this.tail.val;
    this.tail = this.tail.prev;
    if (this.tail) {
      this.tail.next = null;
    } else {
      this.head = null;
    }
    this._size--;
    return val;
  }

  popFront() {
    if (this.empty()) {
      throw new Error("empty deque");
    }
    const val = this.head.val;
    this.head = this.head.next;
    if (this.head) {
      this.head.prev = null;
    } else {
      this.tail = null;
    }
    this._size--;
    return val;
  }
}

function slidingWindowMax(arr, k) {
  let l = 0,
    r = 0;
  const maxQueue = new MaxQueue();
  const res = [];
  while (r < arr.length) {
    maxQueue.push(arr[r]);
    r++;
    if (r - l === k) {
      res.push(maxQueue.max());
      maxQueue.pop();
      l++;
    }
  }
  return res;
}

