class SlidingWindowMax {
  public List<Integer> solve(int[] arr, int k) {
    int l = 0, r = 0;
    MaxQueue maxQueue = new MaxQueue();
    List<Integer> res = new ArrayList<>();
    while (r < arr.length) {
      maxQueue.push(arr[r]);
      r++;
      if (r - l == k) {
        res.add(maxQueue.max());
        maxQueue.pop();
        l++;
      }
    }
    return res;
  }
}

